<?php
final class HppService {
    private PDO $pdo; private CollectionStore $store;
    public function __construct(PDO $pdo,CollectionStore $store){$this->pdo=$pdo;$this->store=$store;}
    private function now(): string{return date(DATE_ATOM);} private function id(string $p): string{return $p.'-'.date('YmdHis').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,6));}
    public function activate(array $p): array {
        $model=trim((string)($p['model_key']??''));if($model==='')throw new RuntimeException('Model HPP wajib dipilih.');$bom=(array)($p['bom_items']??[]);$upah=(array)($p['upah']??[]);$pack=(array)($p['packaging']??[]);$oper=(array)($p['operasional']??[]);$manual=(array)($p['biaya_manual']??[]);
        $material=0;$bomRows=[];foreach($bom as $i=>$it){$qty=(float)($it['qty_pakai_per_pcs']??$it['qty_per_unit']??0);$waste=(float)($it['waste_pct']??0);$price=(float)($it['harga_satuan_pakai']??$it['harga_satuan']??0);$eff=$qty*(1+$waste/100);$cost=$eff*$price;if($qty>0&&$price<=0)throw new RuntimeException('Material '.($it['nama_bahan']??$it['nama_item']??($i+1)).' belum memiliki harga aktif.');$material+=$cost;$bomRows[]=array_merge($it,['id_bom'=>$it['id_bom']??$this->id('BOM'),'model_key'=>$model,'qty_efektif_per_pcs'=>$eff,'hpp_material_per_pcs'=>$cost,'urutan'=>$i+1,'status'=>'Aktif','updated_at'=>$this->now(),'created_at'=>$it['created_at']??$this->now()]);}
        $sumNumeric=function(array $a):float{$s=0;foreach($a as $v){if(is_numeric($v))$s+=(float)$v;elseif(is_array($v))$s+=(float)($v['total']??$v['nominal']??0);}return $s;};$upahTotal=$sumNumeric($upah);$packTotal=$sumNumeric($pack);$manualTotal=$sumNumeric($manual);$opMode=(string)($oper['mode']??'nominal');$op=$opMode==='persen'?($material+$upahTotal)*(float)($oper['persen']??0)/100:(float)($oper['nominal']??0);$hpp=round($material+$upahTotal+$packTotal+$op+$manualTotal);
        if($hpp<=0)throw new RuntimeException('Total HPP harus lebih dari 0.');
        $produk=$this->store->get('produk');$history=$this->store->get('hpp_history');$allBom=$this->store->get('hpp_model_bom');$versions=[];foreach($history as $h)if((string)($h['model_key']??'')===$model&&preg_match('/V(\d+)/i',(string)($h['version']??''),$m))$versions[]=(int)$m[1];$ver='V'.str_pad((string)((max($versions?:[0]))+1),2,'0',STR_PAD_LEFT);$old=0;
        foreach($produk as &$pr){$mk=trim((string)($pr['model_tas']??$pr['nama']??''));if($mk===$model){$old=max($old,(float)($pr['hpp_produk']??0));$pr['hpp_produk']=$hpp;$pr['hpp_version']=$ver;$pr['hpp_updated_at']=$this->now();if(isset($upah['potong']))$pr['upah_potong']=(float)$upah['potong'];if(isset($upah['jahit']))$pr['upah_jahit']=(float)$upah['jahit'];}}
        unset($pr);$allBom=array_values(array_filter($allBom,fn($x)=>(string)($x['model_key']??'')!==$model));foreach($bomRows as $r)$allBom[]=$r;$hist=['id'=>$this->id('HIST'),'tanggal'=>$p['effective_date']??date('Y-m-d'),'model_key'=>$model,'version'=>$ver,'hpp_lama'=>$old,'hpp_baru'=>$hpp,'material_total'=>$material,'upah_total'=>$upahTotal,'packaging_total'=>$packTotal,'operasional_total'=>$op,'manual_total'=>$manualTotal,'formula_snapshot'=>json_encode($p,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'catatan'=>$p['catatan']??'','operator'=>$p['operator']??($_SESSION['username']??'system'),'created_at'=>$this->now()];$history[]=$hist;
        $this->store->put('produk',$produk);$this->store->put('hpp_model_bom',$allBom);$this->store->put('hpp_history',$history);AuditService::log($this->pdo,'ACTIVATE_HPP','HPP',$hist['id'],$model,['hpp'=>$old],['hpp'=>$hpp,'version'=>$ver]);return ['status'=>'success','message'=>'HPP berhasil diaktifkan.','data'=>['model_key'=>$model,'hpp'=>$hpp,'version'=>$ver,'history'=>$hist]];
    }
    public function syncFromPurchases(): array {
        $purchases=$this->store->get('pembelian');$hpp=$this->store->get('bahan_hpp');$bahan=$this->store->get('bahan');$latest=[];
        foreach($purchases as $p){foreach((array)($p['items']??[]) as $it){$id=(string)($it['id_bahan']??'');if($id==='')continue;$price=(float)($it['harga_satuan']??0);if($price<=0&&($it['qty']??0))$price=(float)($it['total_harga']??$it['subtotal']??0)/max(1,(float)$it['qty']);if($price>0)$latest[$id]=$price;}}
        $count=0;foreach($hpp as &$h){$id=(string)($h['id_bahan']??$h['id_bahan_gudang']??'');if(isset($latest[$id])){$h['harga_beli_terakhir']=$latest[$id];$h['price_review_required']=true;$h['updated_at']=$this->now();$count++;}}unset($h);$this->store->put('bahan_hpp',$hpp);return ['status'=>'success','message'=>'Harga pembelian terbaru berhasil disinkronkan untuk '.$count.' material.','updated'=>$count,'data'=>$hpp];
    }
}
